Given an array of integers arr[], determine whether it is possible to split it into two contiguous subarrays (without reordering the elements) such that the sum of the two subarrays is equal. Input : arr[] = [1 , 2 , 3 , 4 , 5 , 5]Output : trueExplanation :The array can be divided after index 3 into two subarrays: [1, 2, 3, 4] and [5, 5].Input : arr[] = [4, 3, 2, 1]Output : falseExplanation: No possible split gives equal sum.Try It YourselfTable of Content[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) Space[Expected Approach] Running Prefix Sum and Suffix Sum - O(n) Time and O(1) Space[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) SpaceUse two loops where the outer loop determines the split position, and the inner loops compute the sum of the left part (including the current index) and the right part (excluding the current index). If the two sums are equal, a valid partition is found.
            C++

    #include <vector>
#include <iostream>
using namespace std;

bool canSplit(vector<int> &arr)
{
    // Try every possible split position
    for (int i = 0; i < arr.size(); i++)
    {
        int leftSum = 0;
        int rightSum = 0;

        // Compute left sum (0 to i)
        for (int j = 0; j <= i; j++)
            leftSum += arr[j];

        // Compute right sum (i+1 to n-1)
        for (int j = i + 1; j < arr.size(); j++)
            rightSum += arr[j];

        // Check condition
        if (leftSum == rightSum)
            return true;
    }

    return false;
}

int main()
{
    vector<int> arr = {1, 2, 3, 4, 5, 5};

    cout << boolalpha << canSplit(arr) << endl;
    return 0;
}


